begin;
update niches set visual_style='{"camera": "crisp 50mm on fresh food and morning routines, gentle overhead breakfast staging, macro on citrus mist and water droplets", "motion": "fresh energizing lift, morning light spreading", "realism": "hyper-photorealistic — citrus pulp glisten, steam from warm drinks, honest healthy skin, dew on greens, physically-based, 8K", "lighting": "bright morning kitchen sun, golden park dawn, soft airy daylight interiors, warm tea-time glow", "reference": "visual language of premium wellness editorials, bright Scandinavian food photography, morning-routine brand films", "atmosphere": "tubuh yang berterima kasih — the body thanked and cared for, quiet daily vitality, prevention as self-respect", "base_style": "bright wellness-lifestyle photography, morning-vitality realism, honest healthy-living warmth", "composition": "one vibrant healthful subject center-frame in airy space, morning-ritual vignettes, hands preparing simple good things", "camera_motion": {"intensity": "sedang"}, "color_grading": "fresh airy grade, clean whites and living greens, warm sunrise accents, gentle contrast", "color_palette": "citrus orange, leaf green, morning white, honey gold, sky soft blue"}'::jsonb, visual_fallbacks='["Glass of warm lemon-honey water in morning window light, steam rising", "Vibrant market greens and citrus arranged in bright natural sun, dew fresh", "Morning stretch silhouette at an open window, park light streaming in", "Bowl of colorful fruit on a clean wooden table, airy kitchen morning", "Restful sleep scene in soft dawn blue, calm breathing, clean linens", "Brisk morning walk through a leafy park, sunlight through the canopy"]'::jsonb, default_hashtags='["#ImunitasTubuh", "#DayaTahanTubuh", "#HidupSehat", "#TipsSehat", "#KesehatanAlami", "#PolaHidupSehat", "#SistemImun", "#SehatAlami", "#VitaminAlami", "#JagaKesehatan"]'::jsonb, youtube_category_id='26', emotion_scoring_criteria='Score 80+ if the climax leaves viewers UPLIFTED AND EMPOWERED — one concrete, doable habit or insight lands so clearly they can start today, framed as self-care not fear. Valid techniques: the everyday habit with surprising immune payoff (with the mechanism), the myth gently corrected with evidence, the small ritual that compounds. STRICT SAFETY: general education only — never diagnose, never cure-claims, never contradict doctors. Score LOW for fear-mongering or miracle promises. Score LOW if advice stays vague (''makan sehat'') instead of concrete and doable tonight.', narration_persona='{"tone": "warm, caring and trustworthy, like a wise friend who genuinely cares", "avoid": "fear-mongering, medical scare tactics, absolute claims, preachy lecturing", "style": "flowing calm rhythm, simple everyday words, reassuring transitions", "hook_style": "question or you_dont_know", "emotion_arc": "curiosity → recognition → relief → motivation"}'::jsonb where niche_id='imunitas_tubuh';
update niches set visual_style='{"camera": "vintage anamorphic 40mm, subtle film grain, shallow depth of field, museum-glass reflections", "motion": "slow ominous push-in, deliberate and grave", "realism": "hyper-photorealistic, aged textures, dust and patina, physically-based, fine micro-detail", "lighting": "low-key candlelight and torchlight, dramatic chiaroscuro, hard single-source shadows, smoky haze", "reference": "visual language of period docudramas, Caravaggio chiaroscuro, NatGeo history features", "atmosphere": "weight of history, moral gravity, ominous inevitability, hushed dread", "base_style": "historical documentary photography, period-accurate, archival cinematic restoration", "composition": "solemn centered subject, rule of thirds, oppressive negative space, foreground artifacts", "camera_motion": {"intensity": "halus"}, "color_grading": "desaturated filmic grade, crushed blacks, warm amber highlights, subtle sepia", "color_palette": "desaturated sepia and ash tones, deep blacks, candlelit ambers, ominous blood-red accents"}'::jsonb, visual_fallbacks='["Fog rolling over an empty WWII trench line at dawn, helmets rusting in the mud", "Declassified file open under a desk lamp, one paragraph blacked out", "Abandoned bunker corridor, flashlight beam finding a wall of scratched names", "Old wartime radio in a dark room, dial glowing, frequency needle trembling", "Aircraft wreck half-swallowed by jungle canopy, seen from above in mist", "Last letter and a pocket watch on a map table, candle burned low"]'::jsonb, default_hashtags='["#MisteriPerangDunia", "#PerangDunia", "#SejarahPerang", "#WW2", "#MisteriSejarah", "#PerangDunia2", "#SejarahDunia", "#KisahPerang", "#FaktaSejarah", "#ArsipRahasia"]'::jsonb, youtube_category_id='27', emotion_scoring_criteria='Score 80+ if the climax lands the FOG-OF-WAR CHILL — the wartime mystery detail (the battalion that vanished, the order never explained, the photo that shouldn''t exist) told with archival precision that makes the unexplained feel documented. Valid techniques: the primary-source fragment (a last radio message, a diary line), the official explanation that raises more questions, the survivor detail that haunts. Score LOW for battle summaries without mystery. Score LOW for conspiracy assertions — the power is in documented uncertainty, not invented answers.', narration_persona='{"tone": "grave war-historian voice, reading declassified files by lamplight", "avoid": "glorifying war, gore for shock, disrespecting victims, conspiracy stated as fact, humor", "style": "declassified-file pacing, coordinates-dates-and-names precision, the human letter inside the giant war, unresolved endings honored", "hook_style": "you_dont_know or story_open about a wartime event that official history cannot explain", "emotion_arc": "intrigue → descent into the fog of war → the inexplicable detail → haunted reflection"}'::jsonb where niche_id='misteri_perang_dunia_c8f3e6';
commit;
